(152480, 7946, 2706, '<td valign="top">haha. is this suggesting something? ;)</td>', 'haha. is this suggesting something? ;)', '2002-11-16 20:58:00.000000', NULL, 1),
(152481, 7946, 5121, '<td valign="top">Crisp image with good strong colours!</td>', 'Crisp image with good strong colours!', '2002-11-17 04:53:00.000000', NULL, 1),
(152482, 7946, 1827, '<td valign="top">Delightful!  I love this.  The focus is dead on - great job.  The framing makes this photo interesting.  In my top ten for the week.  9, just-married</td>', 'Delightful!  I love this.  The focus is dead on - great job.  The framing makes this photo interesting.  In my top ten for the week.  9, just-married', '2002-11-17 12:09:00.000000', NULL, 1);
