INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(153110, 8015, 4388, '<td valign="top">nice lighting and depth of field.  i might have had the camera pointing a little more down to exclude the stuff at the top and include more of the green at the botton, and centered the puff.</td>', 'nice lighting and depth of field.  i might have had the camera pointing a little more down to exclude the stuff at the top and include more of the green at the botton, and centered the puff.', '2002-11-11 19:37:00.000000', NULL, 1),
(153111, 8015, 1880, '<td valign="top">Another flower pic ...  Ugggg ...  I''m tired of flowers ... 6 ...  RLS</td>', 'Another flower pic ...  Ugggg ...  I''m tired of flowers ... 6 ...  RLS', '2002-11-11 23:08:00.000000', NULL, 1),
(153112, 8015, 1031, '<td valign="top">Nice, unusual lighting.</td>', 'Nice, unusual lighting.', '2002-11-12 02:39:00.000000', NULL, 1),
(153113, 8015, 4793, '<td valign="top">Nice shot, composition is nice and all in focus.</td>', 'Nice shot, composition is nice and all in focus.', '2002-11-12 13:38:00.000000', NULL, 1),
(153114, 8015, 3280, '<td valign="top">Nice job!  I like the focus and lighting.  You  may have inporved the composition slightly by either moving in closer or letting the entire plant in the photo.  DPz</td>', 'Nice job!  I like the focus and lighting.  You  may have inporved the composition slightly by either moving in closer or letting the entire plant in the photo.  DPz', '2002-11-12 15:28:00.000000', NULL, 1),
(153115, 8015, 714, '<td valign="top">Very nice 7 Sonifo</td>', 'Very nice 7 Sonifo', '2002-11-12 15:52:00.000000', NULL, 1),
(153116, 8015, 4764, '<td valign="top">I like the offcentered positioning of the flower -hector</td>', 'I like the offcentered positioning of the flower -hector', '2002-11-12 20:36:00.000000', NULL, 1),
(153117, 8015, 4162, '<td valign="top">Lovely lighting and good detail</td>', 'Lovely lighting and good detail', '2002-11-12 21:15:00.000000', NULL, 1),
(153118, 8015, 4625, '<td valign="top">Hmm, if it was cropped a little wider I think it would have been a little better. Overall though, nice shot.</td>', 'Hmm, if it was cropped a little wider I think it would have been a little better. Overall though, nice shot.', '2002-11-13 00:16:00.000000', NULL, 1),
(153119, 8015, 1041, '<td valign="top">challenge -- met<br/>technical -- early morning (or late afternoon for that matter) light is called golden for a reason, isn''t it.  beautiful lighting.  sharpness and focus are also good.<br/>composition -- there are two ways you can go with this one ... include all of the dandilion (which you almost did, but you cropped it on the left!) or make the crop look deliberate and include only part of it.  this way it looks a little accidental, but still nice.<br/>-- gr8photos.</td>', 'challenge -- mettechnical -- early morning (or late afternoon for that matter) light is called golden for a reason, isn''t it.  beautiful lighting.  sharpness and focus are also good.composition -- there are two ways you can go with this one ... include all of the dandilion (which you almost did, but you cropped it on the left!) or make the crop look deliberate and include only part of it.  this way it looks a little accidental, but still nice.-- gr8photos.', '2002-11-13 11:06:00.000000', NULL, 1),
(153120, 8015, 4361, '<td valign="top">did u blow on it afterwards?</td>', 'did u blow on it afterwards?', '2002-11-13 17:46:00.000000', NULL, 1),
(153121, 8015, 4210, '<td valign="top">Feels just slightly off center. A simple crop will clean that up.</td>', 'Feels just slightly off center. A simple crop will clean that up.', '2002-11-13 23:45:00.000000', NULL, 1),
(153122, 8015, 4648, '<td valign="top">Great shot.  Looks like taken at eye level.  Great.  How do you critique a good shot except say "Good shot"  and then give it a 9.  Hard to comment.  PTL  I really like this.  Glad you didn''t sneeze or even breath until after taking it.  My 2 year old grandson loves to blow them</td>', 'Great shot.  Looks like taken at eye level.  Great.  How do you critique a good shot except say "Good shot"  and then give it a 9.  Hard to comment.  PTL  I really like this.  Glad you didn''t sneeze or even breath until after taking it.  My 2 year old grandson loves to blow them', '2002-11-14 00:55:00.000000', NULL, 1),
(153123, 8015, 205, '<td valign="top">could be more centered</td>', 'could be more centered', '2002-11-14 15:03:00.000000', NULL, 1),
(153124, 8015, 2706, '<td valign="top">nice shot</td>', 'nice shot', '2002-11-16 20:31:00.000000', NULL, 1),
