(153875, 8087, 4510, '<td valign="top">nice mix of textures &amp; colour</td>', 'nice mix of textures & colour', '2002-11-11 06:21:00.000000', NULL, 1),
(153876, 8087, 4514, '<td valign="top">Nice.</td>', 'Nice.', '2002-11-11 07:03:00.000000', NULL, 1),
