INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(154510, 8146, 92, '<td valign="top">I LOVE it !!!!! Wonderful color and DOF ! This ALL just works ! 10 Shiiizzzam</td>', 'I LOVE it !!!!! Wonderful color and DOF ! This ALL just works ! 10 Shiiizzzam', '2002-11-15 10:24:00.000000', NULL, 1),
(154511, 8146, 4648, '<td valign="top">Great colors.  Good clean focus.  Short crop, would have loved to see more of the ear.  But still a great 8.  PTL</td>', 'Great colors.  Good clean focus.  Short crop, would have loved to see more of the ear.  But still a great 8.  PTL', '2002-11-16 23:02:00.000000', NULL, 1),
(154512, 8146, 1031, '<td valign="top">I grew this a couple of times when I was a kid. Outstanding assortment of kernel patterns with great detail. How does it look with a non-Technicolor scheme?</td>', 'I grew this a couple of times when I was a kid. Outstanding assortment of kernel patterns with great detail. How does it look with a non-Technicolor scheme?', '2002-11-17 13:24:00.000000', NULL, 1),
(154513, 8146, 2221, '<td valign="top">Is this really corn? It looks more like onions. Very interesting. I don''t know about the leaf in the foreground. On theone hand it seems to distract from the subject but on the other it gives a nice sense of depth. But I think it distracts more that it helps. At least in this position. A little higher would be better. -stephan</td>', 'Is this really corn? It looks more like onions. Very interesting. I don''t know about the leaf in the foreground. On theone hand it seems to distract from the subject but on the other it gives a nice sense of depth. But I think it distracts more that it helps. At least in this position. A little higher would be better. -stephan', '2002-11-17 19:01:00.000000', NULL, 1),
(154514, 8147, 4493, '<td valign="top">Nice composition and lighting. Did you try with polished silver? That would have really made this shot jump off the page.</td>', 'Nice composition and lighting. Did you try with polished silver? That would have really made this shot jump off the page.', '2002-11-11 09:39:00.000000', NULL, 1),
(154515, 8147, 811, '<td valign="top">I like how the shape of this pulls the eyes in and up.  Would have liked it even more if it were just a touch sharper, but a great pic, nonetheless. karmat</td>', 'I like how the shape of this pulls the eyes in and up.  Would have liked it even more if it were just a touch sharper, but a great pic, nonetheless. karmat', '2002-11-11 14:48:00.000000', NULL, 1),
(154516, 8147, 1031, '<td valign="top">Souns like a law firm, looks like Danish furniture. Nice control of the lighting.</td>', 'Souns like a law firm, looks like Danish furniture. Nice control of the lighting.', '2002-11-11 20:52:00.000000', NULL, 1),
(154517, 8147, 5047, '<td valign="top">Cool!</td>', 'Cool!', '2002-11-11 23:20:00.000000', NULL, 1),
(154518, 8147, 4829, '<td valign="top">I like the black &amp; white, it works for this photo. Nicely done-8-CreativeDotCom</td>', 'I like the black & white, it works for this photo. Nicely done-8-CreativeDotCom', '2002-11-12 09:34:00.000000', NULL, 1),
(154519, 8147, 472, '<td valign="top">great composition. forks are a good subject.</td>', 'great composition. forks are a good subject.', '2002-11-12 14:06:00.000000', NULL, 1),
