(154876, 8183, 3127, '<td valign="top">Lacking DOF. Good photo, though.</td>', 'Lacking DOF. Good photo, though.', '2002-11-11 15:29:00.000000', NULL, 1),
(154877, 8183, 4725, '<td valign="top">finally. someone who knows what a macro SHOULD be. <br/>scott.</td>', 'finally. someone who knows what a macro SHOULD be. scott.', '2002-11-11 18:27:00.000000', NULL, 1),
(154878, 8183, 4162, '<td valign="top">Great Macro.  Wonder if  a different colour  background would add to this.</td>', 'Great Macro.  Wonder if  a different colour  background would add to this.', '2002-11-11 20:47:00.000000', NULL, 1),
(154879, 8183, 3859, '<td valign="top">This  is an interesting shot. Good focua.  I like how you can see thru the honey.  I think if you had used a background that was more of a contrast with the honey color, maybe something in a dark color, that the photo would be quite dramatic.</td>', 'This  is an interesting shot. Good focua.  I like how you can see thru the honey.  I think if you had used a background that was more of a contrast with the honey color, maybe something in a dark color, that the photo would be quite dramatic.', '2002-11-12 10:18:00.000000', NULL, 1),
(154880, 8183, 3280, '<td valign="top">Very nice, I love the way the texture is magnified in the honey.  Neat shot.  DPz</td>', 'Very nice, I love the way the texture is magnified in the honey.  Neat shot.  DPz', '2002-11-12 23:22:00.000000', NULL, 1),
(154881, 8183, 4361, '<td valign="top">neat</td>', 'neat', '2002-11-13 17:50:00.000000', NULL, 1),
(154882, 8183, 1041, '<td valign="top">challenge -- met<br/>technical -- nice focus on the drops in the middle of the picture, the texture of the paper makes them look even more interesting.  the OOF drop in the foreground is too dominant for my personal preference, did you try a crop where only part of that drop is visible?<br/>composition -- the little lines of droplets definitely add to the picture.<br/>-- gr8photos.</td>', 'challenge -- mettechnical -- nice focus on the drops in the middle of the picture, the texture of the paper makes them look even more interesting.  the OOF drop in the foreground is too dominant for my personal preference, did you try a crop where only part of that drop is visible?composition -- the little lines of droplets definitely add to the picture.-- gr8photos.', '2002-11-14 17:30:00.000000', NULL, 1),
(154883, 8183, 2716, '<td valign="top">Nice, clean shot.  I like it.  Jacko 8</td>', 'Nice, clean shot.  I like it.  Jacko 8', '2002-11-14 20:00:00.000000', NULL, 1),
(154884, 8183, 4430, '<td valign="top">I wish this wasn''t out of focus in the front, it is distracting and could be quite beautiful</td>', 'I wish this wasn''t out of focus in the front, it is distracting and could be quite beautiful', '2002-11-17 14:27:00.000000', NULL, 1),
(154885, 8183, 4186, '<td valign="top">out of curiousity, is that skin it''s on?</td>', 'out of curiousity, is that skin it''s on?', '2002-11-17 23:04:00.000000', NULL, 1),
