INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(155710, 8257, 4388, '<td valign="top">i like the off-center but would have liked to see the top of the pistol.</td>', 'i like the off-center but would have liked to see the top of the pistol.', '2002-11-11 21:25:00.000000', NULL, 1),
(155711, 8257, 5047, '<td valign="top">Love the color &amp; droplets!</td>', 'Love the color & droplets!', '2002-11-11 23:27:00.000000', NULL, 1),
(155712, 8257, 4305, '<td valign="top">I can see what you mean''t about missing details.  I would have never payed attention to this sharp crisp water droplets on a flower as I passed it by.  What a spectacular macor caputre of this calibur.</td>', 'I can see what you mean''t about missing details.  I would have never payed attention to this sharp crisp water droplets on a flower as I passed it by.  What a spectacular macor caputre of this calibur.', '2002-11-15 14:15:00.000000', NULL, 1),
(155713, 8257, 4648, '<td valign="top">Like the bits of pollen left on the leaf and the water droplets.  Good crop for me.  I don''t know what details you are speaking of but I like the details of the petals.  Very nice clear details.  Great solid 7.  PTL</td>', 'Like the bits of pollen left on the leaf and the water droplets.  Good crop for me.  I don''t know what details you are speaking of but I like the details of the petals.  Very nice clear details.  Great solid 7.  PTL', '2002-11-15 17:10:00.000000', NULL, 1),
(155714, 8257, 1280, '<td valign="top">Pretty, but could be sharper and if the stamen weren''t cut off it would be better.  Grayce</td>', 'Pretty, but could be sharper and if the stamen weren''t cut off it would be better.  Grayce', '2002-11-16 12:48:00.000000', NULL, 1),
(155715, 8257, 1827, '<td valign="top">I wish the pistol weren''t cut off.  It seems to break the soft feel of the image. 5, just-married</td>', 'I wish the pistol weren''t cut off.  It seems to break the soft feel of the image. 5, just-married', '2002-11-16 21:10:00.000000', NULL, 1),
(155716, 8257, 4173, '<td valign="top">The best flower picture submitted this week by far, I can tell a lot of work went into this.  Interesting shot indeed.  I hope this gets a high position this week!! ...10</td>', 'The best flower picture submitted this week by far, I can tell a lot of work went into this.  Interesting shot indeed.  I hope this gets a high position this week!! ...10', '2002-11-17 13:17:00.000000', NULL, 1),
(155717, 8257, 4366, '<td valign="top">I Love this picture. It has great and good detail. This is by far the best out of the bunch</td>', 'I Love this picture. It has great and good detail. This is by far the best out of the bunch', '2002-11-17 20:36:00.000000', NULL, 1),
(155718, 8258, 4986, '<td valign="top">Wow.</td>', 'Wow.', '2002-11-11 00:52:00.000000', NULL, 1),
