(155842, 8266, 3697, '<td valign="top">Very creative. I like the bright, bold colors and the color-changing background. Nice work.</td>', 'Very creative. I like the bright, bold colors and the color-changing background. Nice work.', '2002-11-16 14:02:00.000000', NULL, 1),
(155843, 8266, 1827, '<td valign="top">My definite #1 pick for the week!  Incredible color.  Focus is terrific.  And the idea is just great!  10, just-married</td>', 'My definite #1 pick for the week!  Incredible color.  Focus is terrific.  And the idea is just great!  10, just-married', '2002-11-17 11:47:00.000000', NULL, 1),
(155844, 8266, 1031, '<td valign="top">That''s pretty expressive for a frog. Have you thought about getting him an audition for a Bud commercial?</td>', 'That''s pretty expressive for a frog. Have you thought about getting him an audition for a Bud commercial?', '2002-11-17 13:40:00.000000', NULL, 1),
(155845, 8266, 3859, '<td valign="top">I like how you have used the spoon to show the size of this little fellow.  This is a remarkable photo.  Love the toenail polish. Bet that took some time!!</td>', 'I like how you have used the spoon to show the size of this little fellow.  This is a remarkable photo.  Love the toenail polish. Bet that took some time!!', '2002-11-17 17:54:00.000000', NULL, 1),
(155846, 8266, 2641, '<td valign="top">This shot ROCKS!!<br/></td>', 'This shot ROCKS!!', '2002-11-17 20:09:00.000000', NULL, 1),
